TEST(SilkParams, ExcitationMatchesReference) {
    for (const ExcCase& test : kExcCases) {
        player::audio::opus::RangeDecoder decoder(test.packet, 96);
        std::vector<int16_t> pulses(test.frame_length, 0);
        player::audio::silk::decodePulses(decoder, pulses.data(), test.signal_type,
                                          test.quant_offset, test.frame_length);
        for (int i = 0; i < test.frame_length; ++i) {
            EXPECT_EQ(pulses[i], test.pulses[i]) << "pulse " << i;
        }
    }
}

TEST(SilkParams, GainsMatchReference) {
    for (const GainCase& test : kGainCases) {
        int8_t prev_ind = static_cast<int8_t>(test.prev_ind_in);
        int32_t gain[4] = {};
        player::audio::silk::gainsDequant(gain, test.ind, prev_ind, test.conditional,
                                          test.nb_subfr);
        for (int i = 0; i < test.nb_subfr; ++i) {
            EXPECT_EQ(gain[i], test.gain[i]) << "gain " << i;
        }
        EXPECT_EQ(prev_ind, test.prev_ind_out);
    }
}

TEST(SilkParams, PitchMatchesReference) {
    for (const PitchCaseOut& test : kPitchCases) {
        int lags[4] = {};
        player::audio::silk::decodePitch(test.lag_index, test.contour, lags, test.fs_khz,
                                        test.nb_subfr);
        for (int i = 0; i < test.nb_subfr; ++i) {
            EXPECT_EQ(lags[i], test.lags[i]) << "lag " << i;
        }
    }
}
